__d(function(g,r,_i,a,m,_e,d){"use strict";function e(e){return e&&e.__esModule?e:{default:e}}Object.defineProperty(_e,'__esModule',{value:!0}),Object.defineProperty(_e,"default",{enumerable:!0,get:function(){return q}});var o=r(d[0]),n=e(r(d[1])),s=e(r(d[2])),i=r(d[3]),c=r(d[4]),t=r(d[5]),l=r(d[6]),u=r(d[7]),p=r(d[8]),y=r(d[9]);const b=[['\xbfC\xf3mo busco un producto o un negocio?','En el inicio o en la pesta\xf1a \xabBuscar\xbb escribe lo que necesitas, por ejemplo \xabpollo\xbb o \xabtortillas\xbb. Ver\xe1s los productos que publicaron las tiendas y los negocios que coinciden. Con \xabDisponible ahora\xbb y \xabA domicilio\xbb afinas la lista.'],['\xbfC\xf3mo s\xe9 qu\xe9 tienda me conviene?','En el inicio ves \xabLo m\xe1s barato hoy\xbb y \xabTiendas para ti\xbb, donde eliges ver las m\xe1s cercanas, las mejor calificadas, las que entregan a domicilio o las que est\xe1n abiertas ahora. Cada tienda muestra sus estrellas, su distancia y si lleva tu pedido a casa. Las insignias (\xabM\xe1s cercana\xbb, \xabMejor calificada\xbb, \xabM\xe1s econ\xf3mica\xbb) solo aparecen cuando hay con qu\xe9 comparar, y siempre ves todas las tiendas que tienen lo que buscas.'],['\xbfC\xf3mo funcionan las ideas para cocinar?','En el inicio toca \xabIdeas para cocinar\xbb: elige una idea (\xabalgo barato\xbb, \xabalgo con prote\xedna\xbb, \xabsolo verduras\xbb, \xabun plato fuerte\xbb, \xabuna idea de desayuno\xbb\u2026) o escribe lo que se te antoja. El asistente solo propone cosas con lo que las tiendas publicaron como disponible, te dice en qu\xe9 tienda conseguir cada ingrediente y cu\xe1l te conviene m\xe1s por estrellas, precio o cercan\xeda, sin dejar fuera a las dem\xe1s. Tambi\xe9n te ense\xf1a lo que ya est\xe1 preparado (postres, fresas con crema, comida corrida\u2026). Funciona sin internet y no comparte nada tuyo.'],['Un negocio no tiene productos','Algunos negocios de la comunidad aparecen en el directorio pero todav\xeda no usan Mercaboot. Cuando su due\xf1o se registre, publicar\xe1 lo que tiene.'],['\xbfC\xf3mo aparto o pido productos?','Abre un negocio y toca \xabAgregar\xbb en lo que quieras. Abajo aparece \xabVer carrito\xbb: ah\xed eliges si pasas a recoger o si te lo llevan, c\xf3mo pagas y tocas \xabApartar pedido\xbb. El negocio recibe tu pedido al instante y los productos quedan guardados para ti. Tu carrito es de un solo negocio a la vez.'],['\xbfCu\xe1nto tiempo me guardan el pedido?','Cada negocio decide cu\xe1nto tiempo guarda un pedido (por ejemplo, 1 hora). Lo ves en tu pedido con una cuenta regresiva. Si no llegas o no pagas a tiempo, el pedido se cancela solo y los productos vuelven a estar a la venta para otras personas. Si necesitas m\xe1s tiempo, av\xedsale por el chat: el comerciante puede darte 30 minutos m\xe1s.'],['\xbfC\xf3mo pago?','Hay dos formas: en persona (efectivo, al recoger o al recibir) y, si el negocio la acepta, por transferencia. Con transferencia, cuando el negocio acepta tu pedido ves sus datos de pago; despu\xe9s de transferir toca \xabYa pagu\xe9\xbb y el negocio confirma que lleg\xf3. El pago con tarjeta en l\xednea llegar\xe1 m\xe1s adelante.'],['\xbfPuedo cancelar un pedido?','S\xed, desde el detalle del pedido, mientras no hayas avisado un pago. Si el negocio ya te lo dej\xf3 listo y cancelas, cuenta como un pedido sin recoger. Si en los \xfaltimos 30 d\xedas dejas 2 pedidos aceptados sin recoger, en ese negocio solo podr\xe1s apartar pagando por transferencia (o nada, si no la acepta); con 3, ya no podr\xe1s apartar ah\xed hasta que hables con el due\xf1o.'],['\xbfQu\xe9 es \xabCliente frecuente\xbb?','Es un trato especial que te da el negocio cuando le compras seguido: un descuento en tus pedidos, un regalo o un cup\xf3n. Lo decide el comerciante, no t\xfa. Si un negocio te nombra cliente frecuente, te avisa por el chat, lo ves en tu pedido y en \xabFavoritos\xbb.'],['\xbfPara qu\xe9 sirve guardar en favoritos?','Es tu lista privada de negocios de siempre, para encontrarlos r\xe1pido. Abre un negocio y toca \xabGuardar en favoritos\xbb. El negocio no ve qui\xe9n lo guard\xf3.'],['\xbfC\xf3mo le escribo a un negocio?','Abre el negocio y toca \xabChatear\xbb (o t\xf3calo en la lista). Escribe tu mensaje o usa una respuesta r\xe1pida, como \xab\xbfQu\xe9 hay hoy?\xbb. Tus conversaciones quedan en la pesta\xf1a \xabChats\xbb y te avisamos con un n\xfamero rojo cuando te contesten. Cada pedido aparece como tarjeta en el chat, as\xed los dos hablan del mismo pedido. Solo se puede chatear con los negocios que ya usan Mercaboot.'],['\xbfPor qu\xe9 piden mi ubicaci\xf3n?','Para mostrarte primero los negocios m\xe1s cercanos y decirte a qu\xe9 distancia est\xe1n. Tu ubicaci\xf3n se usa solo en tu tel\xe9fono: no se guarda ni se env\xeda a nadie. Si no quieres darla, la app funciona igual, solo que sin distancias.'],['\xbfC\xf3mo dejo una rese\xf1a?','Abre un negocio, toca la pesta\xf1a \xabRese\xf1as\xbb y luego \xabDejar rese\xf1a\xbb. Elige de 1 a 5 estrellas, marca lo que te gust\xf3 (producto fresco, buen trato, entrega r\xe1pida\u2026) y, si quieres, escribe un comentario. Solo cuenta una rese\xf1a tuya por negocio: si vuelves a opinar, se cambia la anterior. Puedes editarla o quitarla en Perfil \u2192 \xabMis rese\xf1as\xbb. No se puede calificar el negocio propio.'],['\xbfQu\xe9 son los avisos y regalos?','Los negocios publican promociones, productos que ya llegaron o se acabaron, y regalos o detalles en fechas especiales: D\xeda del Amor y la Amistad, D\xeda de las Madres, D\xeda del Padre, D\xeda de Muertos, Navidad, Reyes Magos y m\xe1s. Los ves en el inicio, en la pesta\xf1a \xabAvisos\xbb de cada negocio y en la campana de novedades. Los de \xabYa no hay\xbb y \xabCerrado hoy\xbb duran hasta que termina el d\xeda.'],['\xbfLos productos se actualizan solos?','S\xed. Cuando un comerciante publica algo, lo cambia o marca que ya se acab\xf3, lo ves en tu tel\xe9fono en unos segundos, sin tener que cerrar la app. Lo que otra persona ya apart\xf3 no se puede pedir otra vez: ver\xe1s cu\xe1ntos quedan. Si pierdes el internet ver\xe1s lo \xfaltimo que se guard\xf3.'],['\xbfY si tambi\xe9n quiero vender?','No necesitas otra cuenta. En tu perfil toca \xabAbrir mi negocio\xbb: sigues comprando como cliente y cambias de modo cuando quieras. Si tu negocio ya aparece en la lista de la comunidad, para reclamarlo necesitas el c\xf3digo que el equipo de Mercaboot le da a su due\xf1o.']],v=[['\xbfC\xf3mo publico lo que vendo?','En \xabProductos\xbb toca \xabAgregar producto\xbb y escribe lo que quieras: nombre, precio y unidad. Si vendes para cocinar en casa, deja \xabPara cocinar\xbb (kilo, bolsa, docena\u2026). Si vendes comida, postres, fresas con crema o bebidas, elige \xabYa preparado\xbb y vende por porci\xf3n, vaso, rebanada, orden o lo que uses. Con el interruptor marcas si hay o ya se acab\xf3, y puedes cambiarlo en cualquier momento. Si adem\xe1s escribes cu\xe1ntos tienes en \xabExistencias\xbb, la app lleva la cuenta sola: descuenta lo que entregas y marca \xabAgotado\xbb cuando llega a cero. Tus clientes lo ven en sus tel\xe9fonos en cuanto lo guardas.'],['\xbfC\xf3mo sabe el asistente qu\xe9 tengo?','Lee los nombres de tus productos. Si escribes \xabQuesillo de Oaxaca\xbb o \xabMango\xbb, sabe que es un l\xe1cteo o una fruta; si escribes \xabFresas con crema\xbb o \xabComida corrida\xbb, sabe que ya est\xe1 preparado. Puedes corregir lo que lleva (carne, prote\xedna\u2026) y para cu\xe1ndo sirve al agregar el producto. As\xed tu tienda aparece cuando alguien pide una idea para cocinar.'],['\xbfC\xf3mo me comparan con otras tiendas?','Con justicia: si tu tienda y otra tienen el mismo producto, aparecen las dos. Las insignias solo se dan por algo concreto (m\xe1s cercana, mejor calificada, m\xe1s econ\xf3mica) y las estrellas cuentan con un promedio prudente, as\xed que una sola rese\xf1a no decide. Una tienda nueva sin rese\xf1as no se castiga. Para destacar: mant\xe9n tus productos al d\xeda, responde los chats y ofrece entrega a domicilio.'],['\xbfC\xf3mo publico una promoci\xf3n, un regalo o un aviso?','En la pesta\xf1a \xabAvisos\xbb (o con los botones r\xe1pidos de tu inicio) elige \xabYa no hay\u2026\xbb, \xabYa hay\u2026\xbb, \xabPromoci\xf3n\xbb, \xabRegalo\xbb, \xabCerrado hoy\xbb u otro aviso. \xabYa no hay\u2026\xbb y \xabYa hay\u2026\xbb cambian el producto a agotado o disponible al instante. Para fiestas como el D\xeda de las Madres, D\xeda de Muertos o Navidad, elige la fiesta y toca una idea pensada para tu tipo de negocio: el mensaje se llena solo y lo puedes cambiar. Puedes quitar un aviso cuando quieras.'],['\xbfC\xf3mo respondo a mis clientes?','Cuando un cliente te escribe, aparece un n\xfamero rojo en la pesta\xf1a \xabChats\xbb. \xc1brela, toca la conversaci\xf3n y contesta con tu mensaje o con una respuesta r\xe1pida (\xabS\xed hay\xbb, \xabYa se acab\xf3\xbb, \xabLlega ma\xf1ana\xbb).'],['\xbfC\xf3mo recibo y atiendo pedidos?','Cuando un cliente aparta productos te llega un aviso y un n\xfamero rojo en \xabPedidos\xbb. \xc1brelo y toca \xabAceptar\xbb (o \xabRechazar\xbb). Al aceptar, los productos quedan apartados con una cuenta regresiva. Cuando lo tengas listo toca \xabMarcar listo\xbb; cuando el cliente lo reciba y te pague, toca \xabEntregado y cobrado\xbb.'],['\xbfQu\xe9 pasa si el cliente no viene?','El pedido se cancela solo cuando se acaba el tiempo de apartado y los productos vuelven a estar a la venta, as\xed no se quedan guardados para nadie. Si ves que s\xed viene, puedes darle 30 minutos m\xe1s. Si no lleg\xf3, toca \xabNo se present\xf3\xbb: queda anotado y, si se repite, la app le pide pagar por transferencia antes de apartar y despu\xe9s deja de aceptarle pedidos.'],['\xbfCu\xe1nto tiempo aparto los productos?','T\xfa eliges, de 15 minutos a 24 horas, en \xabPedidos\xbb o en \xabEditar mi negocio\xbb \u2192 \xabPedidos y apartado\xbb. Si un d\xeda no puedes atender pedidos, apaga \xabRecibir pedidos\xbb: tus clientes siguen viendo tus productos y pueden escribirte por el chat.'],['\xbfC\xf3mo cobro por transferencia?','En \xabEditar mi negocio\xbb \u2192 \xabPedidos y apartado\xbb enciende \xabPago por transferencia\xbb y escribe tus datos (banco, CLABE y nombre). Solo los ve el cliente cuando aceptas su pedido. Cuando te avise que ya pag\xf3, revisa tu banco y toca \xabConfirmar pago\xbb. Si no lo ves, toca \xabNo veo el pago\xbb y habla con \xe9l por el chat.'],['\xbfC\xf3mo nombro a un cliente frecuente?','T\xfa decides qui\xe9n lo es. En \xabClientes frecuentes\xbb (en tu inicio o en tu perfil) toca \xabNombrar frecuente\xbb en quien te compra seguido y elige un descuento y/o un beneficio (un regalo, un cup\xf3n). El descuento se aplica solo en sus pedidos y el beneficio aparece en el pedido para que se lo des al entregarlo. Tambi\xe9n puedes hacerlo desde el chat o desde un pedido.'],['\xbfC\xf3mo pongo mi ubicaci\xf3n?','En \xabPerfil\xbb \u2192 \xabEditar mi negocio\xbb, en la secci\xf3n \xab\xbfD\xf3nde est\xe1s?\xbb, toca \xabUsar mi ubicaci\xf3n actual\xbb estando en tu negocio, o pega el enlace de Google Maps. As\xed tus clientes ven qu\xe9 tan cerca est\xe1s y pueden pedir indicaciones. Si tu negocio no est\xe1 en Google Maps no pasa nada: escribe tu direcci\xf3n o una referencia y te encontrar\xe1n igual.'],['\xbfC\xf3mo reclamo un negocio que ya aparece en la lista?','T\xf3calo y escribe su c\xf3digo de reclamo: un c\xf3digo secreto de 12 letras y n\xfameros (como K7M2-9QXP-4HWD) que el equipo de Mercaboot entrega solo al due\xf1o. Sin ese c\xf3digo nadie puede quedarse con tu tienda, ni por error. Antes de terminar, la app te pregunta \xab\xbfEs tu negocio?\xbb y puedes elegir \xabNo, volver\xbb. Si tu negocio no est\xe1 en la lista, elige \xabMi negocio es nuevo\xbb.'],['Reclam\xe9 un negocio por error','En tu perfil, hasta abajo, toca \xabDejar de administrar este negocio\xbb. Tu cuenta sigue como cliente y la tienda vuelve a la lista sin due\xf1o, lista para que su verdadero due\xf1o la reclame con su c\xf3digo.'],['\xbfPuedo cambiar mi logo y mis datos?','S\xed. En \xabPerfil\xbb \u2192 \xabEditar mi negocio\xbb cambias logo, nombre, tel\xe9fono, correo, horario, direcci\xf3n y todo lo dem\xe1s cuando quieras.'],['\xbfY si tambi\xe9n quiero comprar?','Con la misma cuenta. En tu perfil toca \xabVer la app como cliente\xbb. Tu negocio sigue publicado y vuelves cuando quieras con \xabCambiar a modo comerciante\xbb.'],['\xbfPuedo dejar de ser comerciante?','S\xed. En tu perfil, hasta abajo, toca \xabDejar de ser comerciante\xbb (o \xabDejar de administrar este negocio\xbb si era uno de la lista). Tu cuenta sigue como cliente y se quitan de Mercaboot tu negocio, productos, avisos y chats. Si solo quieres comprar un rato, mejor usa \xabVer la app como cliente\xbb.']];function q(){const{cuenta:e}=(0,c.useStore)(),q='comerciante'===e?.rol?v:b,[f,h]=(0,o.useState)(0);return(0,y.jsxs)(l.Screen,{bottomInset:!0,contentStyle:{gap:16,paddingBottom:28},children:[(0,y.jsxs)(s.default,{style:{flexDirection:'row',alignItems:'center',gap:8,paddingTop:4,paddingLeft:8,paddingRight:16},children:[(0,y.jsx)(l.BackBtn,{}),(0,y.jsx)(u.T,{size:18,weight:700,children:"Ayuda"})]}),(0,y.jsxs)(s.default,{style:{gap:16,paddingHorizontal:20},children:[(0,y.jsx)(l.Group,{r:18,children:q.map(([e,o],i)=>(0,y.jsxs)(n.default,{accessibilityRole:"button",onPress:()=>h(f===i?null:i),style:{padding:16,gap:8},children:[(0,y.jsxs)(s.default,{style:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',gap:10},children:[(0,y.jsx)(u.T,{size:15,weight:700,lh:1.3,style:{flex:1},children:e}),(0,y.jsx)(s.default,{style:{transform:[{rotate:f===i?'180deg':'0deg'}]},children:(0,y.jsx)(t.Icon,{name:"down",size:18,color:p.C.muted})})]}),f===i?(0,y.jsx)(u.T,{size:14,lh:1.5,color:p.C.greyText,children:o}):null]},e))}),(0,y.jsxs)(l.Card,{style:{padding:16,gap:6,backgroundColor:p.C.greenTint,borderColor:p.C.greenTint},children:[(0,y.jsx)(u.T,{size:14,weight:700,color:p.C.greenDark,children:"Mercaboot es para tu comunidad"}),(0,y.jsxs)(u.T,{size:13,lh:1.45,color:p.C.greenDark,children:["Hecho para los negocios de ",i.COMUNIDAD,". Tu cuenta, tu negocio, tus productos y tus chats se guardan en la nube, as\xed que se ven al instante en los tel\xe9fonos de los dem\xe1s."]})]})]})]})}},760,[12,245,109,841,839,796,795,797,798,6]);